#!/bin/sh
# Generated by FWShift: an AWS Network Firewall policy and its stateful rule group, created with the AWS CLI. Read the
# report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE    prints the calls, makes none (no AWS access needed)
#   CHECK=1 sh THIS_FILE      sends every call with --dry-run: AWS checks the requests and the permissions
#   sh THIS_FILE              creates the rule group and the policy
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The policy is attached to no firewall: nothing changes for any traffic until you associate it:
#   aws network-firewall associate-firewall-policy --firewall-name FIREWALL --firewall-policy-arn ARN
# A rule group or policy of the same name stops the script before anything is created; a call AWS refuses stops it
# where it is (delete what it made with aws network-firewall delete-rule-group / delete-firewall-policy and run it
# again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws network-firewall' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
TMP=$(mktemp -d) || fail "mktemp"
trap 'rm -rf "$TMP"' EXIT
# free_group NAME / free_policy NAME: stop the script when one of that name exists
free_group() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-rule-group --rule-group-name "$1" --type STATEFUL $AWS_OPTS >/dev/null 2>&1; then
    fail "a rule group named $1 exists already; nothing was created"
  fi
}
free_policy() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-firewall-policy --firewall-policy-name "$1" $AWS_OPTS >/dev/null 2>&1; then
    fail "a firewall policy named $1 exists already; nothing was created"
  fi
}
# group NAME CAPACITY FILE: creates a stateful rule group and prints its ARN
group() {
  if [ -n "$DRY_RUN" ]; then
    show create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3"
    printf 'arn:aws:network-firewall:dryrun:000000000000:stateful-rulegroup/%s\n' "$1"
    return 0
  fi
  if [ -n "$CHECK" ]; then
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --dry-run --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1 (dry run)"
    printf 'checked: rule group %s\n' "$1" >&2
  else
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --description 'Generated by FWShift' --tags Key=fwshift,Value=generated \
      --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1"
    printf 'created %s\n' "$arn" >&2
  fi
  printf '%s\n' "$arn"
}
# policy NAME FILE CHECKFILE: creates the firewall policy (with CHECK, checks it without its rule groups, which a dry run
# does not create)
policy() {
  if [ -n "$DRY_RUN" ]; then show create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2"; return 0; fi
  if [ -n "$CHECK" ]; then
    aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$3" --dry-run $AWS_OPTS >/dev/null \
      || fail "create-firewall-policy $1 (dry run)"
    printf 'checked: firewall policy %s\n' "$1" >&2
    return 0
  fi
  aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2" \
    --description 'Generated by FWShift; review the conversion report before associating it' \
    --tags Key=fwshift,Value=generated $AWS_OPTS >/dev/null || fail "create-firewall-policy $1"
  printf 'created firewall policy %s\n' "$1" >&2
}

# No rule group or policy of these names may exist.
free_group fwshift-rules
free_policy fwshift

# Rule group 1: 30 rules, in the order of the policy.
cat > "$TMP/group1.json" <<'FWSHIFT_JSON'
{
 "RuleVariables": {
  "IPSets": {
   "sources_account_app_example_shop": {
    "Definition": [
     "10.50.2.20/32"
    ]
   },
   "targets_tag_app": {
    "Definition": [
     "10.50.2.20/32",
     "10.60.0.0/24"
    ]
   },
   "targets_tag_db": {
    "Definition": [
     "10.50.3.30/32"
    ]
   }
  }
 },
 "RulesSource": {
  "RulesString": "pass tcp $targets_tag_db any -> 10.50.1.10/31 [443,8443:8444] (msg:\"db-to-vpc+allow-https-web\"; flow:to_server; sid:1; rev:1;)\ndrop ip $targets_tag_db any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32] any (msg:\"db-to-vpc+implied deny ingress\"; flow:to_server; sid:2; rev:1;)\ndrop ip $targets_tag_db any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] any (msg:\"db-no-internet _between instances_\"; flow:to_server; sid:3; rev:1;)\ndrop tcp [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] 25 (msg:\"pol-shop:deny-smtp-out _between instances_\"; flow:to_server; sid:4; rev:1;)\npass tcp 10.50.1.10/31 any -> $targets_tag_app 8080 (msg:\"implied allow egress+allow-app-from-web\"; flow:to_server; sid:5; rev:1;)\npass icmp 10.50.1.10/31 any -> $targets_tag_app any (msg:\"implied allow egress+allow-app-from-web\"; flow:to_server; ip_proto:1; sid:6; rev:1;)\npass tcp $sources_account_app_example_shop any -> $targets_tag_db 5432 (msg:\"implied allow egress+allow-db-from-app\"; flow:to_server; sid:7; rev:1;)\npass tcp [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] any -> 10.50.1.10/31 [443,8443:8444] (msg:\"implied allow egress+allow-https-web\"; flow:to_server; sid:8; rev:1;)\npass tcp 2001:db8:50:1::10/128 any -> 2001:db8:50:1::10/128 443 (msg:\"implied allow egress+allow-https-web-v6\"; flow:to_server; sid:9; rev:1;)\ndrop ip [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24,2001:db8:50:1::10/128] any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24,2001:db8:50:1::10/128] any (msg:\"implied allow egress+implied deny ingress\"; flow:to_server; sid:10; rev:1;)\npass tcp 10.50.1.10/31 any -> $targets_tag_app 8080 (msg:\"allow-app-from-web\"; flow:to_server; sid:11; rev:1;)\npass icmp 10.50.1.10/31 any -> $targets_tag_app any (msg:\"allow-app-from-web\"; flow:to_server; ip_proto:1; sid:12; rev:1;)\npass tcp $sources_account_app_example_shop any -> $targets_tag_db 5432 (msg:\"allow-db-from-app\"; flow:to_server; sid:13; rev:1;)\ndrop tcp 203.0.113.0/24 any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] 22 (msg:\"deny-ssh-blocked\"; flow:to_server; sid:14; rev:1;)\npass tcp 0.0.0.0/0 any -> 10.50.1.10/31 [443,8443:8444] (msg:\"allow-https-web\"; flow:to_server; sid:15; rev:1;)\npass tcp ::/0 any -> 2001:db8:50:1::10/128 443 (msg:\"allow-https-web-v6\"; flow:to_server; sid:16; rev:1;)\npass tcp 198.51.100.0/24 any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] 22 (msg:\"allow-ssh-admins\"; flow:to_server; sid:17; rev:1;)\npass tcp 2001:db8:900::/48 any -> 2001:db8:50:1::10/128 22 (msg:\"allow-mgmt-v6\"; flow:to_server; sid:18; rev:1;)\npass icmp 2001:db8:900::/48 any -> 2001:db8:50:1::10/128 any (msg:\"allow-mgmt-v6\"; flow:to_server; ip_proto:58; sid:19; rev:1;)\ndrop ip 203.0.113.128/25 any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] any (msg:\"pol-shop:deny-tor _in_\"; flow:to_server; sid:20; rev:1;)\npass tcp 198.51.100.200/32 any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] 9100 (msg:\"pol-shop:allow-monitoring _in_\"; flow:to_server; sid:21; rev:1;)\npass tcp 192.0.2.64/26 any -> [10.50.1.10/32,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] 80 (msg:\"pol-ew1:allow-lb-health _in_\"; flow:to_server; sid:22; rev:1;)\ndrop ip any any -> [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24,2001:db8:50:1::10/128] any (msg:\"implied deny ingress _in_\"; flow:to_server; sid:23; rev:1;)\ndrop ip [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] any -> 192.0.2.0/24 any (msg:\"deny-egress-doc\"; flow:to_server; sid:24; rev:1;)\npass ip $targets_tag_db any -> 10.50.0.0/16 any (msg:\"db-to-vpc\"; flow:to_server; sid:25; rev:1;)\ndrop ip $targets_tag_db any -> 0.0.0.0/0 any (msg:\"db-no-internet\"; flow:to_server; sid:26; rev:1;)\npass udp $targets_tag_app any -> 198.51.100.53/32 53 (msg:\"pol-shop:allow-dns-out _out_\"; flow:to_server; sid:27; rev:1;)\npass tcp $targets_tag_app any -> 198.51.100.53/32 53 (msg:\"pol-shop:allow-dns-out _out_\"; flow:to_server; sid:28; rev:1;)\ndrop tcp [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24] any -> 0.0.0.0/0 25 (msg:\"pol-shop:deny-smtp-out _out_\"; flow:to_server; sid:29; rev:1;)\npass ip [10.50.1.10/31,10.50.2.20/32,10.50.3.30/32,10.50.9.5/32,10.60.0.0/24,2001:db8:50:1::10/128] any -> any any (msg:\"implied allow egress _out_\"; flow:to_server; sid:30; rev:1;)\n"
 },
 "StatefulRuleOptions": {
  "RuleOrder": "STRICT_ORDER"
 }
}
FWSHIFT_JSON
G1=$(group fwshift-rules 100 "$TMP/group1.json") || exit 1

# The policy: every packet to the stateful engine, the rule groups in strict order, then the default of the source.
cat > "$TMP/policy.json" <<FWSHIFT_JSON
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"},"StatefulRuleGroupReferences":[{"ResourceArn":"${G1}","Priority":100}]}
FWSHIFT_JSON
cat > "$TMP/policy-check.json" <<'FWSHIFT_JSON'
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"}}
FWSHIFT_JSON
policy fwshift "$TMP/policy.json" "$TMP/policy-check.json"

# Not written:
#   old-dns: disabled in the source
#   pol-shop:geo-and-fqdn (in): disabled in the source

echo 'Done. Associate the policy with a firewall when you are ready; until then nothing changes.' >&2
